package com.bank.strfn.service;
import java.util.logging.*;

public class StatementFormatter {
    private static final Logger log = Logger.getLogger(StatementFormatter.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    // SQL: id || ' - ' || holder
    public String displayLabel(String id, String holder) {
        String label = id + " - " + normalizeName(holder);
        log.info(() -> "displayLabel -> " + label);
        return label;
    }
    // SQL: 'XXXX' || RIGHT(id, 4)
    public String maskAccount(String id) {
        String last4 = id.length() >= 4 ? id.substring(id.length() - 4) : id;
        return "XXXX" + last4;
    }
    // SQL: UPPER(TRIM(holder))
    public String normalizeName(String holder) {
        return holder == null ? "" : holder.trim().toUpperCase();
    }
}
